/** Shared media types. Used by the asset registry (data) and MediaFrame (presentation). */

export type ImageVariant = {
  src: string
  width: number
  height: number
  bytes: number
}

/** A responsive raster image with AVIF + WebP variants (generated by `npm run assets`). */
export type ResponsiveImage = {
  id: string
  /** Describe what the image shows. Empty string only for purely decorative images. */
  alt: string
  /** Intrinsic size of the largest variant — sets the aspect ratio and prevents layout shift. */
  width: number
  height: number
  /** Average colour, painted behind the image while it loads (skipped for transparent images). */
  dominantColor: string
  /** Transparent cut-out (PNG source with alpha). Rendered without a frame background. */
  hasAlpha?: boolean
  avif: readonly ImageVariant[]
  webp: readonly ImageVariant[]
  /** CSS object-position when a frame crops the image, e.g. '50% 20%'. */
  objectPosition?: string
}

/** A muted loop with a poster frame. */
export type VideoAsset = {
  id: string
  /** Describes what happens in the video, for screen readers. */
  label: string
  src: string
  type: 'video/mp4' | 'video/webm'
  poster: ResponsiveImage
  width: number
  height: number
}
